def esc(s): return s.replace("\\", "\\\\").replace('"', '\\"')
root = os.path.join(os.path.dirname(__file__), "..", "Resources", "Localization")
for i, lang in enumerate(LANGS):
    d = os.path.join(root, f"{lang}.lproj")
    os.makedirs(d, exist_ok=True)
    with open(os.path.join(d, "Localizable.strings"), "w", encoding="utf-8") as f:
        f.write("/* Generated by scripts/localize.py. Edit the table there. */\n")
        for key, values in T.items():
            f.write(f'"{esc(key)}" = "{esc(values[i])}";\n')
print(f"{len(T)} strings x {len(LANGS)} languages")
